3532	    // --- The worked examples, live (--printer-live) ------------------------
3533	    //
3534	    // The handoff's worked examples through the real panel: its own session,
3535	    // the live model, the Orca backend. Words and taps go in as the page would
3536	    // send them; each exchange is printed for reading, and what can be checked
3537	    // mechanically is.
3538	
3539	    struct LiveStep
3540	    {
3541	        std::string            label;
3542	        std::function<void()>  act;   // opens a session, or sends words or a tap
3543	        std::function<bool()>  ready; // when the exchange has settled
3544	        std::function<void()>  check; // then
3545	    };
3546	    std::deque<LiveStep>     m_live_steps;
3547	    std::size_t              m_live_printed{0};
3548	    std::string              m_live_printer;
3549	    std::vector<std::string> m_live_added;
3550	    bool                     m_live_wizard_seen{false};
3551	    std::string              m_live_host_printer;
3552	    std::string              m_live_step; // the running step's label
3553	
3554	    // The Orca backend over the harness's own plater, for what the panel's
3555	    // conversation reads through it.
3556	    PrinterSetup::OrcaPrinterBackend& live_backend()
3557	    {
3558	        static PrinterSetup::OrcaPrinterBackend backend(*m_plater, PrinterSetup::PrinterCatalog::load(Slic3r::resources_dir()));
3559	        return backend;
3560	    }
3561	
3562	    PrinterSetup::PrinterPanel* live_panel() const
3563	    {
3564	        ShellController* shell = installed_shell();
3565	        return shell == nullptr ? nullptr : shell->printer_panel();
3566	    }
3567	
3568	    // Opens the panel the way Home and the header do: through the shell, which
3569	    // gives it the whole window.
3570	    void live_show(PrinterSetup::ConversationMode mode, const std::string& printer)
3571	    {
3572	        // The shell refuses to open a chat while one is open, and a close
3573	        // finishes on a later event turn (PrinterPanel::close). So an open
3574	        // chat is closed first, as the person would, and the next is opened
3575	        // once that close has run. Each open step also waits for the panel to
3576	        // show, so it never proceeds on the session being closed.
3577	        const auto open = [mode, printer] {
3578	            installed_shell()->open_printer_conversation(mode == PrinterSetup::ConversationMode::Add ? std::string() : printer,
3579	                                                         mode == PrinterSetup::ConversationMode::Connect);
3580	        };
3581	        // Queued on the panel, where PrinterPanel::close queues its own
3582	        // finish, so the open runs after any close still waiting, this one's
3583	        // or an earlier step's. (The app's queue has no order with it.)
3584	        if (live_panel()->IsShown())
3585	            live_panel()->close();
3586	        live_panel()->CallAfter(open);
3587	    }
3588	
3589	    void live_send(const std::string& type, const nlohmann::json& payload)
3590	    {
3591	        static int next = 0;
3592	        // The person can close the panel before the script is done with it.
3593	        // The step then fails by name, and the next open starts a fresh session.
3594	        Agent::AgentHost* host = live_panel()->host();
3595	        if (host == nullptr) {
3596	            std::string step;
3597	            for (const char c : m_live_step)
3598	                step += std::isalnum(static_cast<unsigned char>(c)) ? static_cast<char>(std::tolower(static_cast<unsigned char>(c))) : '_';
3599	            check(false, "live_panel_open_for_" + step);
3600	            return;
3601	        }
3602	        host->on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
3603	                                             {"version", Agent::Protocol::kVersion},
3604	                                             {"id", "live-" + std::to_string(++next)},
3605	                                             {"type", type},
3606	                                             {"payload", payload}}
3607	                                  .dump());
3608	    }
3609	
3610	    // Whether the app posted a note after this message.
3611	    bool live_note_after(const std::string& message_id) const
3612	    {
3613	        const auto messages = live_messages();
3614	        bool after = false;
3615	        for (const auto& message : messages) {
3616	            if (after && message.role == Agent::MessageRole::Note)
3617	                return true;
3618	            after = after || message.id == message_id;
3619	        }
3620	        return false;
3621	    }
3622	
3623	    // The page's opening is the thread's first line, as the agent's.
3624	    void check_live_opening(const std::string& start, const std::string& name)
3625	    {
3626	        const auto messages = live_messages();
3627	        check(!messages.empty() && messages.front().role == Agent::MessageRole::Assistant &&
3628	                  messages.front().text.rfind(start, 0) == 0,
3629	              name);
3630	    }
3631	
3632	    // --- Pictures of the live run (PRINTER_LIVE_CAPTURE_DIR) ----------------
3633	    //
3634	    // With the variable set, each capture point writes <name>.png of the
3635	    // panel, through WebKit's own snapshot as --printer-connect-capture does.
3636	    void live_capture(const std::string& name)
3637	    {
3638	        const char* dir = std::getenv("PRINTER_LIVE_CAPTURE_DIR");
3639	        if (dir == nullptr)
3640	            return;
3641	        m_state->capture_dir = dir;
3642	        capture_panel(name);
3643	    }
3644	
3645	    void say(const std::string& text)
3646	    {
3647	        static int next = 0;
3648	        live_send("user_message", {{"clientMessageId", "live-c-" + std::to_string(++next)}, {"text", text}});
3649	    }
3650	
3651	    std::vector<Agent::ConversationMessage> live_messages() const
3652	    {
3653	        if (live_panel()->host() == nullptr)
3654	            return {};
3655	        const Agent::ProjectPersistence* persistence = live_panel()->persistence();
3656	        if (persistence == nullptr)
3657	            return {};
3658	        return persistence->document().messages(persistence->document().active_conversation_id());
3659	    }
3660	
3661	    const std::vector<Agent::ToolActivity>& live_activities() const
3662	    {
3663	        static const std::vector<Agent::ToolActivity> none;
3664	        return live_panel()->host() == nullptr ? none : live_panel()->host()->tools().activities();
3665	    }
3666	
3667	    std::vector<const Agent::ToolActivity*> live_calls(const std::string& tool) const
3668	    {
3669	        std::vector<const Agent::ToolActivity*> calls;
3670	        for (const Agent::ToolActivity& activity : live_activities())
3671	            if (activity.tool == tool)
3672	                calls.push_back(&activity);
3673	        return calls;
3674	    }
3675	
3676	    // Settled: nothing streaming, no tool mid-run, and the model has had its
3677	    // last word.
3678	    bool live_settled() const
3679	    {
3680	        Agent::AgentHost* host = live_panel()->host();
3681	        // A panel that closed has nothing more to say; the step's own
3682	        // checks see what closed it.
3683	        if (host == nullptr)
3684	            return true;
3685	        if (host->stream_active())
3686	            return false;
3687	        const auto& activities = live_activities();
3688	        if (!activities.empty()) {
3689	            const Agent::ToolState state = activities.back().state;
3690	            if (state == Agent::ToolState::Running)
3691	                return false;
3692	        }
3693	        // A finished reply with no words is settled too; live_print_new
3694	        // says so, rather than the run waiting on it forever.
3695	        const auto messages = live_messages();
3696	        return !messages.empty() && messages.back().role == Agent::MessageRole::Assistant &&
3697	               messages.back().state == Agent::MessageState::Complete;
3698	    }
3699	
3700	    static const char* tool_state_label(Agent::ToolState state)
3701	    {
3702	        switch (state) {
3703	        case Agent::ToolState::Running: return "running";
3704	        case Agent::ToolState::Succeeded: return "succeeded";
3705	        case Agent::ToolState::Failed: return "failed";
3706	        case Agent::ToolState::Cancelled: return "cancelled";
3707	        }
3708	        return "?";
3709	    }
3710	
3711	    void live_print_new()
3712	    {
3713	        if (live_panel()->host() == nullptr)
3714	            std::cerr << "HARNESS LIVE   (the panel closed)\n";
