3746	    // One receipt per printer added, under a message the thread has.
3747	    bool live_receipt_for(const std::string& printer) const
3748	    {
3749	        const auto receipts = live_receipts();
3750	        if (receipts.size() != 1 || receipts.front()["printer"].value("name", "") != printer)
3751	            return false;
3752	        const auto messages = live_messages();
3753	        return std::any_of(messages.begin(), messages.end(), [&](const Agent::ConversationMessage& message) {
3754	            return message.id == receipts.front().value("afterMessageId", "");
3755	        });
