3853	    void begin_printer_live()
3854	    {
3855	        const char* anthropic = std::getenv("ANTHROPIC_API_KEY");
3856	        const char* openai    = std::getenv("OPENAI_API_KEY");
3857	        if (live_panel() == nullptr || (anthropic == nullptr && openai == nullptr)) {
3858	            fail("the printer panel or an Anthropic or OpenAI key is missing");
3859	            return;
3860	        }
3861	        // The panel builds its own Agent from the app configuration, as the
3862	        // shipped app does, so the key goes there: this run's throwaway data
3863	        // directory, never the person's. With ANTHROPIC_API_KEY the run uses
3864	        // Anthropic, and JUSPRIN_LIVE_MODEL names a cheaper model than the
3865	        // provider's default (claude-haiku-5-5, say).
3866	        // As a std::string: a char* would pick AppConfig::set's bool overload.
3867	        if (anthropic != nullptr) {
3868	            wxGetApp().app_config->set("jusprin_agent", "anthropic_api_key", std::string(anthropic));
