175	    void DeviceManager::on_machine_alive(std::string json_str)
176	    {
177	        try {
178	            json j = json::parse(json_str);
179	            std::string dev_name        = j["dev_name"].get<std::string>();
180	            std::string dev_id          = j["dev_id"].get<std::string>();
181	            std::string dev_ip          = j["dev_ip"].get<std::string>();
182	            std::string printer_type_str= j["dev_type"].get<std::string>();
183	            std::string printer_signal  = j["dev_signal"].get<std::string>();
184	            std::string connect_type    = j["connect_type"].get<std::string>();
185	            std::string bind_state      = j["bind_state"].get<std::string>();
186	
187	            if (connect_type == "farm") {
188	                connect_type ="lan";
189	                bind_state   = "free";
190	            }
191	
192	            std::string sec_link = "";
193	            std::string ssdp_version = "";
194	            if (j.contains("sec_link")) {
195	                sec_link = j["sec_link"].get<std::string>();
196	            }
197	            if (j.contains("ssdp_version")) {
198	                ssdp_version = j["ssdp_version"].get<std::string>();
199	            }
200	            std::string connection_name = "";
201	            if (j.contains("connection_name")) {
202	                connection_name = j["connection_name"].get<std::string>();
203	            }
204	
205	            MachineObject* obj;
206	
207	            /* update userMachineList info */
208	            auto it = userMachineList.find(dev_id);
209	            if (it != userMachineList.end()) {
210	                if (it->second->get_dev_ip() != dev_ip ||
211	                    it->second->bind_state != bind_state ||
212	                    it->second->bind_sec_link != sec_link ||
213	                    it->second->dev_connection_type != connect_type ||
214	                    it->second->bind_ssdp_version != ssdp_version)
215	                {
216	                    if (it->second->bind_state != bind_state) {
217	                        OnMachineBindStateChanged(it->second, bind_state);
218	                    }
219	
220	                    it->second->set_dev_ip(dev_ip);
221	                    it->second->bind_state          = bind_state;
222	                    it->second->bind_sec_link       = sec_link;
223	                    it->second->dev_connection_type = connect_type;
224	                    it->second->bind_ssdp_version   = ssdp_version;
225	                    BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << " UpdateUserMachineInfo"
226	                        << ", dev_id= " << dev_id
227	                        << ", ip = "  <<dev_ip
228	                        << ", printer_name= " << dev_name
229	                        << ", con_type= " << connect_type << ", signal= " << printer_signal
230	                        << ", bind_state= " << bind_state;
231	                }
232	            }
233	
234	            /* update localMachineList */
235	            it = localMachineList.find(dev_id);
236	            if (it != localMachineList.end()) {
237	                // update properties
238	                /* ip changed */
239	                obj = it->second;
240	
241	                if (obj->get_dev_ip().compare(dev_ip) != 0) {
242	                    if ( connection_name.empty() ) {
243	                        BOOST_LOG_TRIVIAL(info) << "MachineObject IP changed from " << obj->get_dev_ip()
244	                                                << " to " << dev_ip;
245	                        obj->set_dev_ip(dev_ip);
246	                    }
247	                    else {
248	                        if ( obj->dev_connection_name.empty() || obj->dev_connection_name.compare(connection_name) == 0) {
249	                            BOOST_LOG_TRIVIAL(info) << "MachineObject IP changed from " << obj->get_dev_ip()
250	                                                    << " to " << dev_ip << " connection_name is " << connection_name;
251	                            if(obj->dev_connection_name.empty()){obj->dev_connection_name = connection_name;}
252	                            obj->set_dev_ip(dev_ip);
253	                        }
254	                    }
255	                    /* ip changed reconnect mqtt */
256	                }
257	
258	                if (obj->wifi_signal != printer_signal ||
259	                    obj->dev_connection_type != connect_type ||
260	                    obj->bind_state != bind_state ||
261	                    obj->bind_sec_link != sec_link ||
262	                    obj->bind_ssdp_version != ssdp_version ||
263	                    obj->printer_type != _parse_printer_type(printer_type_str))
264	                {
265	                    if (obj->dev_connection_type != connect_type ||
266	                        obj->bind_state != bind_state ||
267	                        obj->bind_sec_link != sec_link ||
268	                        obj->bind_ssdp_version != ssdp_version ||
269	                        obj->printer_type != _parse_printer_type(printer_type_str))
270	                    {
271	                        BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << " UpdateLocalMachineInfo"
272	                            << ", dev_id= " << dev_id
273	                            << ", ip = " << dev_ip
274	                            << ", printer_name= " << dev_name
275	                            << ", con_type= " << connect_type << ", signal= " << printer_signal
276	                            << ", bind_state= " << bind_state;
277	                    }
278	                    else
279	                    {
280	                        BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << " UpdateLocalMachineInfo_WIFI"
281	                            << ", dev_id= " << dev_id
282	                            << ", ip = "  << dev_ip
283	                            << ", printer_name= " << dev_name
284	                            << ", con_type= " << connect_type << ", signal= " << printer_signal
285	                            << ", bind_state= " << bind_state;
286	                    }
287	
288	                    obj->wifi_signal         = printer_signal;
289	                    obj->dev_connection_type = connect_type;
290	                    obj->bind_state          = bind_state;
291	                    obj->bind_sec_link       = sec_link;
292	                    obj->bind_ssdp_version   = ssdp_version;
293	                    obj->printer_type        = _parse_printer_type(printer_type_str);
