535	std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
536	                                               const std::string& access_code)
537	{
538	    // The same printer asked for again keeps waiting; anything else replaces
539	    // the attempt below.
540	    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
541	        connection(name).state == "connecting")
542	        return {};
543	    const auto info = connection(name);
544	    if (info.provider != "bambu" || info.state == "unavailable")
545	        return info.message;
546	    if (std::none_of(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; }))
547	        return "Choose a matching printer from the refreshed list.";
548	    auto* devices = wxGetApp().getDeviceManager();
549	    MachineObject* machine = devices->get_my_machine(device_id);
550	    if (!machine)
551	        machine = devices->get_local_machine(device_id);
552	    if (!machine)
553	        return "That printer is no longer available. Refresh the list and try again.";
554	    if (machine->is_lan_mode_printer()) {
555	        if (access_code.empty() && !machine->has_access_right())
556	            return "Enter the access code shown on your printer.";
557	        if (!std::all_of(access_code.begin(), access_code.end(), [](unsigned char c) {
558	                return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
559	            }))
560	            return "The access code can only contain letters and numbers.";
561	    }
562	    const wxString problem = Printers::link_named_printer(name, device_id);
563	    if (!problem.empty())
564	        return problem.ToStdString();
565	    prepare_connection(name);
566	    if (machine->is_lan_mode_printer() && !access_code.empty())
567	        machine->set_user_access_code(access_code);
568	    m_connection_attempt = ConnectionAttempt{name, device_id, std::chrono::steady_clock::now(),
569	                                              std::chrono::system_clock::now()};
570	    if (devices->get_selected_machine() != machine) {
571	        devices->set_selected_machine(device_id);
572	        return {};
573	    }
574	    // Selecting the selected LAN printer again disconnects and reconnects
575	    // it, and GUI_App's local-connect handler hears the disconnect one event
576	    // turn later and clears the selection -- after the reconnect. Deselect
577	    // now, and select it again once that notice has run.
578	    m_connection_attempt->reselecting = true;
579	    devices->set_selected_machine("");
580	    wxGetApp().CallAfter([alive = std::weak_ptr<bool>(m_alive), this, device_id] {
581	        if (alive.expired() || !m_connection_attempt || m_connection_attempt->device_id != device_id)
582	            return;
583	        m_connection_attempt->reselecting = false;
584	        wxGetApp().getDeviceManager()->set_selected_machine(device_id);
585	    });
586	    return {};
587	}
