589	std::string OrcaPrinterBackend::connect_host(const std::string& name, const std::string& host_type,
590	                                            const std::string& address, const std::string& api_key)
591	{
592	    const auto info = connection(name);
593	    if (info.provider != "host" || info.state == "unavailable")
594	        return info.message;
595	    if (host_type != "moonraker" && host_type != "octoprint")
596	        return "Choose Moonraker or OctoPrint.";
597	    if (address.empty() || address.find_first_of("\r\n\t @") != std::string::npos)
598	        return "Enter the printer's host name, IP address or HTTP URL without credentials.";
599	    if (address.find("://") != std::string::npos && address.rfind("http://", 0) != 0 && address.rfind("https://", 0) != 0)
600	        return "Use an HTTP or HTTPS address.";
601	    const auto* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
602	    if (!preset)
603	        return "This printer was renamed or removed.";
604	    // Reuse a saved secret only for the same endpoint and provider.
605	    const std::string key = api_key.empty() && address == info.address && host_type == info.host_type ?
606	        preset->config.opt_string("printhost_apikey") : api_key;
607	    // Tested on a copy: the printer's own settings change only once the host
608	    // has answered (settle).
609	    DynamicPrintConfig config = preset->config;
610	    config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(host_type == "moonraker" ? htMoonraker : htOctoPrint));
611	    config.set_key_value("print_host", new ConfigOptionString(address));
612	    config.set_key_value("printhost_apikey", new ConfigOptionString(key));
613	    std::unique_ptr<PrintHost> host(PrintHost::get_print_host(&config));
614	    if (!host)
615	        throw std::logic_error("A supported print host has no adapter");
616	    // PrintHost::test blocks until the host answers, and a host that accepts
617	    // the connection and never replies holds it with no upper bound (Http's
618	    // DEFAULT_TIMEOUT_MAX is 0). So it runs on a thread of its own, as
619	    // upstream's upload queue runs these adapters. Nothing waits for it:
620	    // joining could hold the panel's close for as long as the host dawdles,
621	    // and kConnectionWait reports the failure meanwhile. The adapter keeps
622	    // copies of what it read from `config`.
623	    auto verdict = std::make_shared<std::atomic<HostVerdict>>(HostVerdict::Testing);
624	    std::thread([host = std::move(host), verdict] {
625	        wxString detail;
626	        verdict->store(host->test(detail) ? HostVerdict::Passed : HostVerdict::Failed);
627	    }).detach();
628	    m_host_attempt = HostAttempt{name, host_type, address, key, std::chrono::steady_clock::now(), std::move(verdict), "connecting", {}};
629	    return {};
630	}
