645	Result PrinterConversation::connection_status(const std::string& name, const std::string& message_id)
646	{
647	    if (saved(name).name.empty())
648	        return refuse("no_printer", "There is no saved printer to connect yet: add one first.");
649	    // For a Bambu Lab printer this starts looking for it on the network, once;
650	    // see m_prepared.
651	    if (m_prepared != name) {
652	        m_backend.prepare_connection(name);
653	        m_prepared = name;
654	        m_search.reset();
655	    }
656	    const PrinterConnectionInfo info = m_backend.connection(name);
657	    if (info.needs_network_plugin)
658	        show_plugin_needed(message_id);
659	    if (!m_search && info.provider == "bambu" && info.state != "unavailable")
660	        m_search = NetworkSearch{std::chrono::steady_clock::now()};
661	    // What this read lists, the model now knows: no note need say it again.
662	    // A printer already reached needs no search to report on, however it is
663	    // reached.
664	    if (m_search && (found_on_network(info) || info.state == "verified"))
665	        m_search->found = true;
666	    return ok(connection_json(info, search_json(info)));
667	}
