130	        if (query.changed_only && std::find(changed.begin(), changed.end(), def.key) == changed.end())
131	            continue;
132	        const std::string key = ascii_lower(def.key), label = ascii_lower(def.label), description = ascii_lower(def.description);
133	        std::size_t matched = 0, best = 4;
134	        for (const std::string& term : terms) {
135	            // A key that holds the term ranks with the keys that start with it:
136	            // "support" finds enable_support among the support_ keys.
137	            const std::size_t rank = key == term ? 0 : key.find(term) != std::string::npos ? 1 : label.find(term) != std::string::npos ? 2 :
138	                                     description.find(term) != std::string::npos ? 3 : 4;
139	            if (rank < 4) {
140	                ++matched;
141	                best = std::min(best, rank);
142	            }
143	        }
144	        if (matched > 0)
145	            matches.emplace_back((terms.size() - matched) * 4 + best, &def);
146	    }
147	    std::sort(matches.begin(), matches.end(), [](const auto& a, const auto& b) {
148	        return a.first < b.first || (a.first == b.first && a.second->key < b.second->key);
149	    });
150	    if (offset > matches.size()) {
151	        result.error = SettingIssue{"", "invalid_arguments", "Settings cursor is past the last match. Search again."};
152	        return result;
153	    }
154	    const std::size_t end = offset + std::min(query.limit, matches.size() - offset);
155	    for (std::size_t i = offset; i < end; ++i)
156	        result.items.push_back(*matches[i].second);
157	    result.truncated = end < matches.size();
158	    if (result.truncated)
159	        result.next_cursor = "offset:" + std::to_string(end);
160	    return result;
161	}
162	
163	inline std::vector<std::string> setting_words(const std::string& key)
164	{
165	    std::vector<std::string> words;
166	    std::size_t start = 0;
167	    for (std::size_t end; (end = key.find('_', start)) != std::string::npos; start = end + 1)
168	        words.push_back(key.substr(start, end - start));
169	    words.push_back(key.substr(start));
170	    return words;
171	}
172	
173	inline std::vector<std::string> setting_suggestions(const std::string& key,
174	                                                    const std::vector<SettingDefinition>& definitions)
175	{
176	    // Edit distance handles misspellings, and shared words handle guessed
177	    // names ("enable_brim" for "brim_type"), without a second alias catalog.
178	    // More shared words first, writable settings before read-only ones, then
179	    // the closer spelling.
180	    using Rank = std::tuple<std::size_t, bool, std::size_t, std::string>;
181	    std::vector<Rank> ranked;
182	    const std::string needle = ascii_lower(key);
183	    const auto words = setting_words(needle);
184	    for (const auto& def : definitions) {
185	        std::vector<std::size_t> row(def.key.size() + 1);
186	        std::iota(row.begin(), row.end(), 0);
187	        for (std::size_t i = 0; i < needle.size(); ++i) {
188	            std::size_t diagonal = row[0];
189	            row[0] = i + 1;
190	            for (std::size_t j = 0; j < def.key.size(); ++j) {
191	                const auto old = row[j + 1];
192	                row[j + 1] = std::min({row[j] + 1, old + 1, diagonal + (needle[i] != def.key[j])});
193	                diagonal = old;
194	            }
195	        }
196	        // "enable" alone says nothing about which setting was meant; with a
197	        // word that does ("support_enable"), it counts.
198	        std::size_t shared = 0;
199	        bool        telling = false;
200	        for (const auto& word : words)
201	            if (word.size() >= 4 && ("_" + def.key + "_").find("_" + word + "_") != std::string::npos) {
202	                ++shared;
203	                telling = telling || word != "enable";
204	            }
205	        if (!telling)
206	            shared = 0;
207	        if (shared > 0 || row.back() <= std::max<std::size_t>(2, needle.size() / 3))
208	            ranked.emplace_back(std::numeric_limits<std::size_t>::max() - shared, !def.writable, row.back(), def.key);
209	    }
210	    std::sort(ranked.begin(), ranked.end());
211	    std::vector<std::string> result;
212	    for (std::size_t i = 0; i < std::min<std::size_t>(3, ranked.size()); ++i)
213	        result.push_back(std::get<3>(ranked[i]));
214	    return result;
215	}
216	
217	inline std::vector<SettingChange> previewed_changes(const SettingsPreview& preview)
218	{
219	    auto result = preview.changes;
220	    result.insert(result.end(), preview.dependencies.begin(), preview.dependencies.end());
221	    return result;
222	}
223	
224	} // namespace Slic3r::GUI::JusPrin::Workspace
